static_assert(sizeof(kParachuteGlb) == 5528);

// Per-shape span tables (#886), indexed by BuiltinShape ordinal. A shape with no wreck variant
// (projectiles despawn on death; Unknown is a bug marker) points its damaged entry at the intact
// span, so callers never branch on "has wreck".
static const std::span<const uint8_t> kShapeSpans[static_cast<size_t>(BuiltinShape::Count)] = {
    {kUnknownGlb, sizeof(kUnknownGlb)},         {kAircraftGlb, sizeof(kAircraftGlb)},
    {kMissileGlb, sizeof(kMissileGlb)},         {kBombGlb, sizeof(kBombGlb)},
    {kRocketGlb, sizeof(kRocketGlb)},           {kGroundVehicleGlb, sizeof(kGroundVehicleGlb)},
    {kNavalVesselGlb, sizeof(kNavalVesselGlb)}, {kStructureGlb, sizeof(kStructureGlb)},
    {kParachuteGlb, sizeof(kParachuteGlb)},
};

static const std::span<const uint8_t> kShapeDamagedSpans[static_cast<size_t>(BuiltinShape::Count)] = {
    {kUnknownGlb, sizeof(kUnknownGlb)},
    {kAircraftDamagedGlb, sizeof(kAircraftDamagedGlb)},
    {kMissileGlb, sizeof(kMissileGlb)},
    {kBombGlb, sizeof(kBombGlb)},
    {kRocketGlb, sizeof(kRocketGlb)},
    {kGroundVehicleDamagedGlb, sizeof(kGroundVehicleDamagedGlb)},
    {kNavalVesselDamagedGlb, sizeof(kNavalVesselDamagedGlb)},
    {kStructureDamagedGlb, sizeof(kStructureDamagedGlb)},
    {kParachuteGlb, sizeof(kParachuteGlb)}, // no wreck — the chute is an Effect and despawns on landing
};

std::span<const uint8_t> builtinShapeGlb(BuiltinShape shape) noexcept {
    const auto i = static_cast<size_t>(shape);
    return kShapeSpans[i < static_cast<size_t>(BuiltinShape::Count) ? i : 0]; // out-of-range -> Unknown
}

std::span<const uint8_t> builtinDamagedShapeGlb(BuiltinShape shape) noexcept {
    const auto i = static_cast<size_t>(shape);
    return kShapeDamagedSpans[i < static_cast<size_t>(BuiltinShape::Count) ? i : 0];
}

std::span<const uint8_t> builtinFloorPlaneGlb() noexcept {
    return {kFloorPlaneGlb, sizeof(kFloorPlaneGlb)};
}

TerrainManifest builtinWorldTerrainManifest() noexcept {
    // Cube-sphere quadtree world (#472): six face roots refined to level 12
    // (~30 m per mesh quad on Earth). Procedural tiles cover any TileKey, so no
    // extent fields are needed.
    return {"world", 12};
}

